laneYaml:
id: rt-prompt-shields-taint
version: 1
priority: 2000
mode: enforce
purpose: Taint sessions on indirect prompt injection and require judging for tainted actions.
appliesTo: { surfaces: [claude-code], agents: ['rt-prompt-shields-taint'] }
failMode: { default: closed, READ: open, NETWORK: closed }
rules: { deny: [], allow: [], judge: [], approve: [] }
defaultVerdict: allow
approval: { channels: [dashboard], timeoutSec: 1 }
judge: { escalateBelow: 0.7, dataPolicy: redacted, timeoutMs: 25 }
promptShields: { enabled: true, scan: [NETWORK], taintTtlActions: 3 }
